import{_ as a,o as n,c as l,a2 as e}from"./chunks/framework.BZO4qERu.js";const M=JSON.parse('{"title":"Mysql","description":"","frontmatter":{},"headers":[],"relativePath":"backend/database/mysql.md","filePath":"backend/database/mysql.md","lastUpdated":1781086744000}'),o={name:"backend/database/mysql.md"};function p(t,s,i,c,d,y){return n(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="mysql" tabindex="-1">Mysql <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;Mysql&quot;">​</a></h1><h2 id="mysql和sqlite区别" tabindex="-1">Mysql和SQLite区别 <a class="header-anchor" href="#mysql和sqlite区别" aria-label="Permalink to &quot;Mysql和SQLite区别&quot;">​</a></h2><ul><li>SQLITE功能简约，小型化，追求最大磁盘效率</li><li>MYSQL功能全面，综合化，追求最大并发效率。 如果只是单机上用的，数据量不是很大，需要方便移植或者需要频繁读/写磁盘文件的话，就用SQLite比较合适；如果是要满足多用户同时访问，或者是网站访问量比较大是使用MYSQL比较合适。</li></ul><h2 id="对比-innodb-和-myisam" tabindex="-1">对比 InnoDB 和 MyISAM <a class="header-anchor" href="#对比-innodb-和-myisam" aria-label="Permalink to &quot;对比 InnoDB 和 MyISAM&quot;">​</a></h2><p>InnoDB 和 MyISAM 是 MySQL 中常用的两种存储引擎。</p><p>InnoDB：InnoDB 是 MySQL 默认的事务性引擎，也是最重要和使用最广泛的存储引擎。它被设计成为大量的短期事务，短期事务大部分是正常提交的，很少被回滚。InnoDB 的性能与自动崩溃恢复的特性，使其在非事务存储需求中也非常流行。除非有特别的原因需要使用其他的存储引擎，否则应该优先考虑 InnoDB 引擎。</p><p>MyISAM：在 MySQL 5.5 及之前版本，MyISAM 是默认引擎。MyISAM 提供大量特性，包括全文索引，压缩，空间函数 等，但 MyISAM 不支持事务以及行级锁，而且一个毫无疑问的缺陷是崩溃后无法安全恢复。正是由于 MyISAM 的缘故，即使 MySQL 已经支持事务很长时间，很多人的概念里还认为 MySQL 不支持事务。尽管这样，MyISAM 并不是一无是处。对于只读的数据，或者表比较小，可以忍受修复操作，依然可以使用 MyISAM。</p><p>总结几个区别：</p><ol><li>InnoDB 支持事务，MyISAM 不支持事务。<strong>这是 MySQL 将默认存储引擎从 MyISAM 变成 InnoDB 的重要因素</strong>。</li><li>InnoDB 支持外键，MyISAM 不支持。对一个包含外键的 InnoDB 表转换为 MyISAM 会失败。</li><li>InnoDB 是聚簇索引，而 MyISAM 是非聚簇索引。聚簇索引的文件放在主键索引的叶子结点上，因此 InnoDB 必须要有主键，而且通过主键索引效率很高。而 MyISAM 是非聚簇索引，数据文件和索引是分离的，索引保存的是数据文件的指针，主键索引和辅助索引是独立的。</li><li>InnoDB 不保存表的具体行数，执行 <code>select count(*) from table</code> 时需要全表扫描，而 MyISAM 用一个变量保存了整个表的行数，执行上述语句只需要读出该变量即可，很快。</li><li>InnoDB 的最小锁粒度是行级锁；MyISAM 是表级锁，一个更新语句会锁住整张表，导致其他查询和更新都会被阻塞，因此并发访问受限，<strong>这也是 MySQL 将默认存储引擎换成 InnoDB 的重要原因</strong>。</li></ol><p>再看看如何选择：</p><ol><li>是否要支持事务。如果需要支持事务，请选择 InnoDB。</li><li>如果表中绝大多数操作都是只读查询，可以考虑 MyISAM；如果既有读写也挺频繁，请使用 InnoDB。</li><li>系统崩溃后，MyISAM 恢复更难，能否接受这一一点。</li><li>MySQL 5.5 后 InnoDB 已经成为 MySQL 的默认引擎（之前是 MyISAM），说明其优势是有目共睹的。如果不知道用什么存储引擎，就用 InnoDB。</li></ol><h2 id="mysql-远程访问问题" tabindex="-1">Mysql 远程访问问题 <a class="header-anchor" href="#mysql-远程访问问题" aria-label="Permalink to &quot;Mysql 远程访问问题&quot;">​</a></h2><ol><li>设置 <code>bind_address</code>。</li></ol><p>首先要确保 <code>[mysqld]</code>中<code>bind_address</code> 参数设置为 <code>0.0.0.0</code>（或者直接注释掉这一行）。</p><p>在 Ubuntu 16.04 + Mysql 5.7 搭配中，该参数的配置位于 <code>/etc/mysql/mysql.conf.d/mysqld.cnf</code>中。</p><p>检查这一步做好的方法就是通过 <code>netstat -tunlp | grep mysql</code> 的方式来确认 <code>mysqld</code> 进程绑定的地址是 <code>0.0.0.0</code> 而不是 <code>127.0.0.1</code>。</p><ol start="2"><li>设置用户权限。</li></ol><p>首先我们可以查看当前数据库中用户在不同IP地址下的访问情况。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql&gt; use mysql;</span></span>
<span class="line"><span>Database changed</span></span>
<span class="line"><span>mysql&gt; select host, user from user;</span></span>
<span class="line"><span>+-----------+------------------+</span></span>
<span class="line"><span>| host      | user             |</span></span>
<span class="line"><span>+-----------+------------------+</span></span>
<span class="line"><span>| localhost | debian-sys-maint |</span></span>
<span class="line"><span>| localhost | mysql.session    |</span></span>
<span class="line"><span>| localhost | mysql.sys        |</span></span>
<span class="line"><span>| localhost | root             |</span></span>
<span class="line"><span>+-----------+------------------+</span></span></code></pre></div><p>以上信息说明，对于 root 用户，现在只能在 localhost 下访问。</p><p>现在假设我们要对 root 用户赋予所有所有IP下的访问权限，则可以在 Mysql 中运行以下命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GRANT ALL PRIVILEGES ON *.* TO &#39;root&#39;@&#39;%&#39; IDENTIFIED BY &#39;password&#39;;</span></span></code></pre></div><p>接下来我们再通过以上命令查看用户的访问情况</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql&gt; select host,user from user;</span></span>
<span class="line"><span>+-----------+------------------+</span></span>
<span class="line"><span>| host      | user             |</span></span>
<span class="line"><span>+-----------+------------------+</span></span>
<span class="line"><span>| %         | root             |</span></span>
<span class="line"><span>| localhost | debian-sys-maint |</span></span>
<span class="line"><span>| localhost | mysql.session    |</span></span>
<span class="line"><span>| localhost | mysql.sys        |</span></span>
<span class="line"><span>| localhost | root             |</span></span>
<span class="line"><span>+-----------+------------------+</span></span></code></pre></div><p>证明 root 用户 已经可以在外部所有IP下进行访问了。</p>`,25)])])}const h=a(o,[["render",p]]);export{M as __pageData,h as default};
